package com.example.yuejie;
import android.app.*;import android.content.*;import android.os.*;import org.json.*;import java.io.*;import java.util.*;
public final class PageChecks extends TurnChecks {
 public void onStart(){output=new File(getTargetContext().getFilesDir(),"global-pages-evidence");output.mkdirs();Bundle result=new Bundle();try{if(args.getString("phase","").startsWith("cold-")){coldPages(args.getString("phase"));result.putString("stream","PASS "+args.getString("phase"));finish(Activity.RESULT_OK,result);return;}if(!"probe".equals(args.getString("phase"))){runChecks();result.putString("stream","PASS global pages "+checks.length()+" checks");finish(Activity.RESULT_OK,result);return;}LocalLibrary db=new LocalLibrary(getTargetContext());NovelApi api=new NovelApi(getTargetContext(),db);String book=args.getString("book","7678661500596145214");JSONObject p=api.profile("content");List<String[]> pairs=api.contentPairs(p);pairs.add(new String[]{"book_id",book});pairs.add(new String[]{"need_version","true"});pairs.add(new String[]{"book_type","0"});JSONObject data=api.signed("/reading/bookapi/directory/all_items/v/",pairs,p,null);try(Writer w=new OutputStreamWriter(new FileOutputStream(new File(output,"metadata-probe.json")),"UTF-8")){w.write(data.toString());}record("metadata_code",data.optInt("code",-1));result.putString("stream","PASS metadata probe");finish(Activity.RESULT_OK,result);}catch(Throwable e){result.putString("stream",android.util.Log.getStackTraceString(e));finish(Activity.RESULT_CANCELED,result);}}
 void coldPages(String phase)throws Exception{
  File expectedFile=new File(output,"cold-expected.json");db=new LocalLibrary(getTargetContext());JSONObject original=db.progress(book);launchMain();reader=(ReaderActivity)startActivitySync(new Intent(getTargetContext(),ReaderActivity.class).putExtra("book_id",book).putExtra("book_name","我在精神病院学斩神").addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));
  try{indexed();waitFor(()->(reader.index==0||reader.layouts.containsKey(reader.index-1))&&(reader.index==reader.directory.length()-1||reader.layouts.containsKey(reader.index+1)),40,"cold neighbors");JSONObject current=state().put("id",reader.chapter.optString("id")).put("offset",reader.anchor);
   if(phase.equals("cold-seed")){try(Writer w=new OutputStreamWriter(new FileOutputStream(expectedFile),"UTF-8")){w.write(current.toString());}record("cold_seed",current);}
   else{JSONObject expected;try(InputStream in=new FileInputStream(expectedFile)){expected=new JSONObject(new String(ProtocolCrypto.read(in),"UTF-8"));}assertTrue(expected.getString("label").equals(current.getString("label"))&&expected.getString("id").equals(current.getString("id"))&&expected.getInt("offset")==current.getInt("offset"),"fresh process resumes exact global page, total, percent and text anchor");record("cold_process_resume",current);shot("cold-process-resume");}
  }finally{if(reader!=null)ui(()->reader.finish());if(original!=null)db.progress(book,original.optString("chapter"),original.optInt("offset"),original.optInt("index"),original.optInt("total"),original.optString("title"));try(Writer w=new OutputStreamWriter(new FileOutputStream(new File(output,phase+".json")),"UTF-8")){w.write(new JSONObject().put("checks",checks).toString(2));}}
 }
 void modelParity()throws Exception{
  JSONObject fixture=asset("page-model-reference.json");JSONArray rows=fixture.getJSONArray("catalog");
  for(String key:new String[]{"font24","font25"}){JSONObject cfg=fixture.getJSONObject(key);long sum=0;int first=0;for(int i=0;i<rows.length();i++){JSONObject row=rows.getJSONObject(i);int count=TomatoPageModel.pages(row.getString("title").length(),row.getInt("chars"),cfg.getDouble("font"),cfg.getDouble("line"),cfg.getDouble("para"),cfg.getDouble("width"),cfg.getDouble("height"));sum+=count;if(i<3)first+=count;}
   if(cfg.has("predicted"))assertTrue(sum==cfg.getLong("predicted"),"official initial model total");JSONArray actual=cfg.getJSONArray("actual");long corrected=sum-first;for(int i=0;i<3;i++)corrected+=actual.getInt(i);assertTrue(corrected==cfg.getLong("corrected"),"official corrected model total "+key);record("official_model_matches_device_"+key,new JSONObject().put("predicted",sum).put("corrected",corrected));
  }
 }
 void indexed()throws Exception{ready();waitFor(()->reader.bookPages!=null,45,"global index ready");waitForIdleSync();SystemClock.sleep(500);}
 JSONObject state()throws Exception{ReaderSurface.Frame f=reader.surface.frame;BookPageIndex p=reader.bookPages;return new JSONObject().put("chapter",f.chapterIndex).put("local",f.pageIndex+1).put("localTotal",f.layout.pages.size()).put("page",p.page(f)).put("total",p.total()).put("percent",p.percent(f)).put("label",reader.bookProgress(f));}
 void runChecks()throws Exception{
  originalPrefs=new JSONObject(getTargetContext().getSharedPreferences("ReaderActivity",0).getAll());db=new LocalLibrary(getTargetContext());originalPosition=db.progress(book);
  try{
   modelParity();launchReader();select(PageTurnMode.NONE);indexed();waitFor(()->reader.layouts.containsKey(1),40,"next chapter layout");
   JSONObject first=state();assertTrue(first.getLong("page")==1&&first.getLong("total")>first.getInt("localTotal"),"first global page and whole book total");record("first_global_page",first);shot("first-global-page");
   swipe(950,900,950,900,30);indexed();JSONObject next=state();assertTrue(next.getLong("page")==first.getLong("page")+1&&next.getDouble("percent")>first.getDouble("percent"),"forward increments global page and weighted percent");record("next_global_page",next);shot("second-global-page");
   swipe(130,900,130,900,30);indexed();assertTrue(reader.bookPages.page(reader.surface.frame)==1,"previous page restores global page");record("previous_page",true);
   page(reader.surface.frame.layout.pages.size()-1);long end=reader.bookPages.page(reader.surface.frame);ui(()->reader.surface.turn(1));indexed();assertTrue(reader.index==1&&reader.bookPages.page(reader.surface.frame)==end+1,"cross chapter globally continuous");record("cross_chapter_forward",state());shot("cross-chapter");ui(()->reader.surface.turn(-1));indexed();assertTrue(reader.index==0&&reader.bookPages.page(reader.surface.frame)==end,"reverse crosses to previous global page");record("cross_chapter_backward",true);
   ui(()->reader.open(1,0));indexed();waitFor(()->reader.layouts.containsKey(0)&&reader.layouts.containsKey(2),40,"neighbor counts");page(2);int offset=reader.anchor;String chapter=reader.chapter.optString("id");long total=reader.bookPages.total();String profile=reader.bookPages.profile;
   ui(()->{reader.showSettings();});tap(reader,"A＋");indexed();assertTrue(!profile.equals(reader.bookPages.profile)&&offset==reader.anchor&&chapter.equals(reader.chapter.optString("id")),"font change rebuilds global index without moving text");record("font_rebuild_preserves_anchor",state().put("beforeTotal",total));shot("font-settings");ui(()->reader.hideOverlays());
   // Cached metadata and actual counts must support a fresh reader instance without a network call.
   waitFor(()->reader.layouts.containsKey(0)&&reader.layouts.containsKey(2),40,"new font neighbors");JSONObject before=state();ui(()->reader.save());ActivityMonitor monitor=addMonitor(ReaderActivity.class.getName(),null,false);ui(()->reader.recreate());ReaderActivity recreated=(ReaderActivity)monitor.waitForActivityWithTimeout(10000);removeMonitor(monitor);assertTrue(recreated!=null,"reader recreated");reader=recreated;indexed();waitFor(()->reader.layouts.containsKey(0)&&reader.layouts.containsKey(2),40,"restored neighbors");JSONObject after=state();assertTrue(reader.anchor==offset&&reader.chapter.optString("id").equals(chapter)&&before.getString("label").equals(after.getString("label")),"reopen restores exact anchor and global label");record("reopen_global_progress",after);shot("reopened-global-page");
   String stable=reader.bookProgress(reader.surface.frame);ui(()->reader.applyDirectory(reader.directory));indexed();assertTrue(stable.equals(reader.bookProgress(reader.surface.frame)),"same directory refresh retains exact global label");record("directory_refresh_rebuild",true);
   NovelApi offline=new NovelApi(getTargetContext(),db,(url,headers,body)->{throw new IOException("controlled offline metadata");});JSONArray cached=offline.pageMetadata(book,reader.directory);assertTrue(NovelApi.metadataCovers(cached,reader.directory),"metadata cache works without network");record("offline_native_metadata",cached.length());
   JSONArray missing=new JSONArray(reader.directory.toString());missing.put(new JSONObject().put("id","999999999999999999").put("title","new"));assertTrue(!NovelApi.metadataCovers(cached,missing),"new chapter cannot silently reuse incomplete metadata");record("new_catalog_requires_word_metadata",true);

   ui(()->reader.open(reader.directory.length()-1,Integer.MAX_VALUE));indexed();assertTrue(reader.bookPages.page(reader.surface.frame)==reader.bookPages.total()&&Math.abs(reader.bookPages.percent(reader.surface.frame)-100)<.00001,"last page is global total and 100 percent");record("last_global_page",state());shot("last-global-page");
   // Different chapter lengths must weight percent by words rather than chapter count.
   ReaderSurface.Frame f=reader.surface.frame;BookPageIndex p=reader.bookPages;assertTrue(p.wordPrefix[p.words.length]>100,"complete native chapter word metadata");record("native_word_metadata_complete",p.words.length);
  }finally{if(reader!=null)ui(()->reader.finish());if(originalPrefs!=null)restorePrefs(originalPrefs);if(originalPosition!=null)db.progress(book,originalPosition.optString("chapter"),originalPosition.optInt("offset"),originalPosition.optInt("index"),originalPosition.optInt("total"),originalPosition.optString("title"));try(Writer w=new OutputStreamWriter(new FileOutputStream(new File(output,"results.json")),"UTF-8")){w.write(new JSONObject().put("checks",checks).toString(2));}}
 }

}
